pub fn numpy_insert<T>(arr: Vec<T>, idx: usize, value: T) -> Vec<T> {
    let len = arr.len();
    assert!(idx <= len, "idx must be within 0..=arr.len()");

    let cap = len.checked_add(1).expect("length overflow");
    let mut result = Vec::with_capacity(cap);

    // Move elements into result without cloning.
    for (i, elem) in arr.into_iter().enumerate() {
        if i == idx {
            result.push(value);
        }
        result.push(elem);
    }

    // If inserting at the end, we never hit i == idx in the loop.
    if idx == len {
        result.push(value);
    }

    debug_assert_eq!(result.len(), len + 1);
    result
}